import React, { useEffect, useRef, useState, useCallback } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const GlbTest = () => {
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const clockRef = useRef(new THREE.Clock());
  const [isPlaying, setIsPlaying] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('Loading...');
  const [error, setError] = useState(null);
  const modelsRef = useRef([]);
  const [activeCategory, setActiveCategory] = useState(null);

  const drawingCanvasRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);

  const categories = [
    { name: 'Head', assets: ['/static/images/head1.png', '/static/images/head2.png', '/static/images/head3.png'] },
    { name: 'Top', assets: ['/static/images/top1.png', '/static/images/top2.png', '/static/images/top3.png'] },
    { name: 'Bottom', assets: ['/static/images/bottom1.png', '/static/images/bottom2.png', '/static/images/bottom3.png'] },
    { name: 'Shoes', assets: ['/static/images/shoes1.png', '/static/images/shoes2.png', '/static/images/shoes3.png'] },
    { name: 'Accessory', assets: ['/static/images/accessory1.png', '/static/images/accessory2.png', '/static/images/accessory3.png'] },
    { name: 'Expression', assets: [] },
  ];

  const selectCategory = (category) => {
    setActiveCategory(category);
  };

  const loadModel = useCallback((modelPath, onLoad) => {
    const loader = new GLTFLoader();

    loader.load(
      modelPath,
      (gltf) => {
        const model = gltf.scene;
        sceneRef.current.add(model);

        const mixer = new THREE.AnimationMixer(model);
        let action = null;

        if (gltf.animations.length > 0) {
          action = mixer.clipAction(gltf.animations[0]);
          action.setLoop(THREE.LoopRepeat);
          action.clampWhenFinished = true;
          action.paused = true;
        }

        modelsRef.current.push({ model, mixer, action });
        updateCameraView();

        if (onLoad) onLoad();
        setLoadingStatus('Loaded Successfully');
      },
      (xhr) => {
        if (xhr.lengthComputable) {
          const percentComplete = (xhr.loaded / xhr.total) * 100;
          setLoadingStatus(`${Math.round(percentComplete)}% loaded`);
        }
      },
      (error) => {
        console.error('Error loading GLB file:', error);
        setError(`Failed to load model: ${error.message}`);
        setLoadingStatus('Load Failed');
      }
    );
  }, []);

  const updateCameraView = useCallback(() => {
    if (modelsRef.current.length === 0) return;

    const box = new THREE.Box3();
    modelsRef.current.forEach(({ model }) => {
      box.expandByObject(model);
    });

    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    const maxDim = Math.max(size.x, size.y, size.z);
    const fov = cameraRef.current.fov * (Math.PI / 180);
    let cameraZ = Math.abs(maxDim / 2 / Math.tan(fov / 2));
    cameraZ *= 1.5;

    cameraRef.current.position.set(center.x, center.y, center.z + cameraZ);
    cameraRef.current.lookAt(center);
    cameraRef.current.updateProjectionMatrix();
  }, []);

  useEffect(() => {
    if (!canvasRef.current) return;

    const initThreeJS = () => {
      sceneRef.current = new THREE.Scene();
      cameraRef.current = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);

      rendererRef.current = new THREE.WebGLRenderer({ antialias: true, canvas: canvasRef.current });
      rendererRef.current.setSize(400, 400);
      rendererRef.current.setClearColor(0xcccccc);

      const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
      sceneRef.current.add(ambientLight);

      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
      directionalLight.position.set(2, 2, 2);
      sceneRef.current.add(directionalLight);

      cameraRef.current.position.z = 5;
    };

    initThreeJS();
    loadModel('/static/models/body__animated_test.glb', () => setLoadingStatus('Loaded Successfully'));

    const animate = () => {
      requestAnimationFrame(animate);

      const delta = clockRef.current.getDelta();
      modelsRef.current.forEach(({ mixer }) => mixer.update(delta));

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }
    };

    animate();

    return () => {
      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, [loadModel, updateCameraView]);

  const toggleAnimation = () => {
    const newIsPlaying = !isPlaying;
    setIsPlaying(newIsPlaying);
    modelsRef.current.forEach(({ action }) => {
      if (action) {
        action.paused = !newIsPlaying;
        if (newIsPlaying) {
          action.play();
        } else {
          action.stop();
        }
      }
    });
  };

  const startDrawing = (e) => {
    setIsDrawing(true);
    draw(e);
  };

  const draw = (e) => {
    if (!isDrawing) return;
    const canvas = drawingCanvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#000000';

    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
  };

  const stopDrawing = () => {
    setIsDrawing(false);
    const canvas = drawingCanvasRef.current;
    const ctx = canvas.getContext('2d');
    ctx.beginPath();
  };

  return (
    <div>
      <canvas ref={canvasRef} style={{ width: '400px', height: '400px', border: '1px solid black' }} />
      <div style={{ marginTop: '10px' }}>
        <p>Status: {loadingStatus}</p>
        {error && <p style={{ color: 'red' }}>{error}</p>}
      </div>
      <button 
        onClick={toggleAnimation}
        disabled={loadingStatus !== 'Loaded Successfully'}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          fontSize: '14px',
          marginRight: '10px'
        }}
      >
        {isPlaying ? 'Pause Animations' : 'Start Animations'}
      </button>

      {/* Category Buttons */}
      <div>
        {categories.map((category) => (
          <button
            key={category.name}
            onClick={() => selectCategory(category)}
            style={{ margin: '10px', padding: '5px 10px', fontSize: '14px' }}
          >
            {category.name}
          </button>
        ))}
      </div>

      {/* Asset Images Feed or Drawing Canvas */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', marginTop: '10px' }}>
        {activeCategory && activeCategory.name === 'Expression' ? (
          <canvas
            ref={drawingCanvasRef}
            width={360}
            height={360}
            style={{ border: '1px solid black' }}
            onMouseDown={startDrawing}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
          />
        ) : (
          activeCategory && activeCategory.assets.map((asset, index) => (
            <img
              key={index}
              src={asset}
              alt={`Asset ${index}`}
              style={{ width: '90px', height: '90px', cursor: 'pointer', border: '1px solid black' }}
              onClick={() => loadModel(`/static/models/${activeCategory.name.toLowerCase()}_${index + 1}.glb`)}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default GlbTest;
